--
-- Name: rag_stats; Type: VIEW; Schema: public; Owner: ai_user
--

CREATE VIEW public.rag_stats AS
 SELECT 'document_embeddings'::text AS table_name,
    count(*) AS total_records,
    count(DISTINCT document_embeddings.user_id) AS unique_users,
    count(DISTINCT document_embeddings.project_id) AS unique_projects,
    pg_relation_size('public.document_embeddings'::regclass) AS table_size_bytes
   FROM public.document_embeddings
UNION ALL
 SELECT 'message_embeddings'::text AS table_name,
    count(*) AS total_records,
    count(DISTINCT message_embeddings.project_id) AS unique_users,
    count(DISTINCT message_embeddings.project_id) AS unique_projects,
    pg_relation_size('public.message_embeddings'::regclass) AS table_size_bytes
   FROM public.message_embeddings
UNION ALL
 SELECT 'public_embeddings'::text AS table_name,
    count(*) AS total_records,
    count(DISTINCT public_embeddings.category) AS unique_users,
    0 AS unique_projects,
    pg_relation_size('public.public_embeddings'::regclass) AS table_size_bytes
   FROM public.public_embeddings;


